import { createHash } from "node:crypto";
import { promises as fs } from "node:fs";
import path from "node:path";

// Exact generator-owned outputs, not a wildcard for declaration/generated files.
// Configuration, route sources and lockfiles remain inputs to those generators.
export const generatedBenchmarkOutputs = Object.freeze({
  "apps/farm/src/farm.d.ts": "Generated by Farm.js. Do not edit.",
  "apps/farm/src/farm-routes.d.ts": "Auto-generated route types",
  "apps/farm/src/farm-env.d.ts": "Auto-generated env types",
  "apps/farm/src/farm-images.d.ts": "Generated by Farm.js",
  "apps/farm/src/farm-i18n.d.ts": "Generated by Farm.js",
  "apps/farm/src/lib/api.generated.ts": "Auto-generated API router types",
  "apps/tanstack/src/routeTree.gen.ts": "This file was automatically generated by TanStack Router.",
  "apps/next/next-env.d.ts": "NOTE: This file should not be edited",
});

export function generatedOutputExclusions(benchmarkGitPath) {
  return Object.keys(generatedBenchmarkOutputs).map(
    (file) => `:(exclude,literal)${benchmarkGitPath}/${file}`,
  );
}

export async function inspectGeneratedOutputs(benchmarkDir) {
  const outputs = {};
  for (const [relativePath, marker] of Object.entries(generatedBenchmarkOutputs)) {
    const absolutePath = path.join(benchmarkDir, relativePath);
    let stat;
    try {
      stat = await fs.lstat(absolutePath);
    } catch (error) {
      if (error.code !== "ENOENT") throw error;
      outputs[relativePath] = null;
      continue;
    }
    if (!stat.isFile())
      throw new Error("Generated benchmark output must be a regular file: " + relativePath);
    const contents = await fs.readFile(absolutePath);
    if (!contents.toString("utf8").includes(marker)) {
      throw new Error(
        "Refusing to treat an unrecognized file as generated output: " +
          relativePath +
          ". Preserve it and use a clean benchmark checkout.",
      );
    }
    outputs[relativePath] = createHash("sha256").update(contents).digest("hex");
  }
  return outputs;
}
